<?php /** @var array<string,mixed> $q */ /** @var list<array<string,mixed>> $items */ /** @var bool $canCreate */ /** @var bool $canSend */ /** @var bool $canDecide */ /** @var bool $canInvoice */ /** @var bool $profileOk */
/** @var list<array<string,mixed>> $projects */ $url = '/quotations/' . $q['public_id']; $st = $q['status']; $v = static fn (string $k, string $d = ''): string => old($k, $d);
$labels = ['draft' => 'Draft', 'sent' => 'Sent', 'accepted' => 'Accepted', 'rejected' => 'Declined', 'expired' => 'Expired', 'withdrawn' => 'Withdrawn']; ?>
<div class="page-head"><div><p class="eyebrow">Quotation</p><h1><?= e($q['reference']) ?> · <?= e($q['title']) ?></h1></div><div class="actions"><a class="btn btn-ghost" href="<?= e($url) ?>/pdf">Download PDF</a><a class="btn btn-ghost" href="/quotations">&larr; Quotations</a></div></div>
<div class="panel"><div class="detail-grid"><div><span class="muted">Status</span><br><span class="badge badge-bq-<?= e($st) ?>"><?= e($labels[$st] ?? $st) ?></span></div><div><span class="muted">Client</span><br><a href="/clients/<?= e($q['client_public_id']) ?>"><?= e($q['client_name']) ?></a></div>
    <div><span class="muted">Total</span><br><strong><?= e(money($q['total_minor'])) ?></strong></div><div><span class="muted">Valid until</span><br><?= $q['valid_until'] ? e(local_date($q['valid_until'])) : '—' ?></div></div>
    <?php if ($q['decided_at']) : ?><p><?= e($labels[$st] ?? $st) ?> on <?= e(local_time($q['decided_at'])) ?> (<?= e((string) $q['decision_channel']) ?>)<?= $q['decision_note'] ? ': ' . e($q['decision_note']) : '' ?></p><?php endif; ?>
    <?= \Vertex\Core\View::partial('billing-lines', ['items' => $items, 'subtotal' => (int) $q['total_minor'], 'discount' => 0, 'total' => (int) $q['total_minor']]) ?>
    <?php if ($q['client_notes']) : ?><h3>Notes for the client</h3><p class="prewrap"><?= e($q['client_notes']) ?></p><?php endif; ?>
    <?php if ($q['internal_notes']) : ?><h3>Internal notes <span class="badge badge-sensitive">staff only</span></h3><p class="prewrap"><?= e($q['internal_notes']) ?></p><?php endif; ?>
    <p class="muted">Accepting a quotation records agreement only. It does not create a payment, change a project price or make any commission eligible.</p></div>
<?php if ($st === 'draft' && $canSend) : ?><div class="panel"><h2>Send to the client</h2><form method="post" action="<?= e($url) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="send"><button class="btn btn-primary btn-sm" type="submit">Send</button></form><p class="muted">The client sees it in their portal and is notified there.</p></div><?php endif; ?>
<?php if ($st === 'draft' && $canCreate) : ?><div class="panel"><h2>Edit draft</h2><form method="post" action="<?= e($url) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="edit">
    <div class="field"><label for="p">Project</label><select id="p" name="project"><option value="">None</option><?php foreach ($projects as $p) : ?><option value="<?= e($p['public_id']) ?>"<?= ($q['project_public_id'] ?? '') === $p['public_id'] ? ' selected' : '' ?>><?= e($p['code']) ?> · <?= e($p['title']) ?></option><?php endforeach; ?></select></div>
    <div class="field"><label for="t">Title</label><input id="t" name="title" required maxlength="200" value="<?= e($v('title', $q['title'])) ?>"></div><div class="field"><label for="vu">Valid until</label><input id="vu" name="valid_until" type="date" value="<?= e($v('valid_until', (string) $q['valid_until'])) ?>"></div>
    <?= \Vertex\Core\View::partial('billing-items', ['items' => $items]) ?>
    <div class="field"><label for="cn">Notes for the client</label><textarea id="cn" name="client_notes" rows="3" maxlength="3000"><?= e($v('client_notes', (string) $q['client_notes'])) ?></textarea></div>
    <div class="field"><label for="in">Internal notes</label><textarea id="in" name="internal_notes" rows="2" maxlength="3000"><?= e($v('internal_notes', (string) $q['internal_notes'])) ?></textarea></div>
    <div class="form-actions"><button class="btn btn-ghost btn-sm" type="submit">Save</button></div></form></div><?php endif; ?>
<?php if ($st === 'sent' && $canSend) : ?><div class="panel"><h2>Withdraw</h2><form method="post" action="<?= e($url) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="withdraw"><div class="field"><label for="wr">Reason (required)</label><input id="wr" name="reason" required minlength="5" maxlength="255"></div><div class="form-actions"><button class="btn btn-ghost btn-sm" type="submit">Withdraw</button></div></form></div><?php endif; ?>
<?php if ($st === 'sent' && $canDecide) : ?><div class="panel"><h2>Record a decision received outside the portal</h2><form method="post" action="<?= e($url) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="decision">
    <div class="field"><label for="dd">Decision</label><select id="dd" name="decision"><option value="accept">Client accepted</option><option value="reject">Client declined</option></select></div><div class="field"><label for="dn">How and when did the client tell you?</label><input id="dn" name="note" required minlength="5" maxlength="500"></div>
    <div class="form-actions"><button class="btn btn-ghost btn-sm" type="submit">Record</button></div></form></div><?php endif; ?>
<?php if ($st === 'accepted' && $canInvoice) : ?><div class="panel"><h2>Invoice</h2><?php if ($q['invoice_public_id']) : ?><p><a href="/invoices/<?= e($q['invoice_public_id']) ?>">Open the invoice created from this quotation</a></p><?php else : ?>
    <form method="post" action="<?= e($url) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="invoice"><button class="btn btn-primary btn-sm" type="submit">Create a draft invoice from this quotation</button></form><?php endif; ?></div><?php endif; ?>
